script:
(function () {
  'use strict';
  // Take-home paycheck estimate for tax year 2026 (annual figures, divided evenly by pay periods).
  //   FICA wages     = gross - Section 125 pre-tax deductions (401(k) deferrals stay FICA-taxable)
  //   Federal wages  = gross - 401(k) deferral - other pre-tax deductions
  //   Taxable income = federal wages + other income - max(standard, itemized) - senior deduction
  //   Federal tax    = progressive brackets - child/dependent credits (not below zero)
  // This is an annual liability estimate, not the IRS Pub. 15-T withholding table.
  // Verified (Node, scratch tests): single, $75,000, biweekly, 5% 401(k), $100/paycheck pre-tax:
  //   federal wages $68,650, taxable $52,550, federal tax $6,273.00 (1,240 + 4,560 + 22% x 2,150),
  //   SS $4,488.80, Medicare $1,049.80. MFJ $100,000 no deductions: taxable $67,800,
  //   tax $7,640.00. SS capped at $11,439.00 at the $184,500 wage base; Additional Medicare
  //   0.9% on wages over $200,000 ($250,000 salary -> $4,075.00 Medicare).
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21).
  // Additional standard deduction (65+), child tax credit, senior deduction: IRC 63(f),
  //   24(h) and 151(d)(5)(C) as amended by P.L. 119-21, inflation-adjusted per Rev. Proc. 2025-32.
  // Social Security wage base and rates: SSA 2026 COLA fact sheet. Medicare: IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var ADDITIONAL_65 = { single: 2050, hoh: 2050, mfj: 1650, mfs: 1650 }; // per person 65+
  var SENIOR_DEDUCTION = 6000;           // per person 65+, 2025-2028, not for married filing separately
  var SENIOR_PHASEOUT_RATE = 0.06;
  var SENIOR_PHASEOUT_START = { single: 75000, hoh: 75000, mfj: 150000, mfs: 0 };
  var CHILD_CREDIT = 2200;               // per child under 17
  var OTHER_DEPENDENT_CREDIT = 500;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_WITHHOLD_START = 200000;
  var ELECTIVE_DEFERRAL_LIMIT = 24500;   // 401(k)/403(b) employee limit before catch-up
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });

  function num(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) {
        tax += (Math.min(taxable, upper) - lower) * RATES[i];
        marginal = RATES[i];
      }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  function compute(o) {
    var gross = o.gross;
    var k401 = gross * o.k401Pct / 100;
    var pretax = Math.min(o.pretaxPer * o.periods, Math.max(0, gross - k401));
    var ficaWages = Math.max(0, gross - pretax);
    var fedWages = Math.max(0, gross - k401 - pretax);
    var agi = fedWages + o.otherIncome;

    var seniors = (o.you65 ? 1 : 0) + (o.status === 'mfj' && o.spouse65 ? 1 : 0);
    var standard = STANDARD_DEDUCTION[o.status] + seniors * ADDITIONAL_65[o.status];
    var senior = 0;
    if (o.status !== 'mfs' && seniors > 0) {
      var each = Math.max(0, SENIOR_DEDUCTION - SENIOR_PHASEOUT_RATE * Math.max(0, agi - SENIOR_PHASEOUT_START[o.status]));
      senior = each * seniors;
    }
    var deduction = Math.max(standard, o.itemized) + senior;
    var taxable = Math.max(0, agi - deduction);
    var bt = bracketTax(taxable, BRACKETS[o.status]);

    var credits = o.kids * CHILD_CREDIT + o.otherDeps * OTHER_DEPENDENT_CREDIT;
    var over = Math.max(0, agi - CREDIT_PHASEOUT_START[o.status]);
    credits = Math.max(0, credits - Math.ceil(over / 1000) * 50);
    var federal = Math.max(0, bt.tax - credits);

    var ss = SS_RATE * Math.min(ficaWages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * ficaWages + ADDL_MEDICARE_RATE * Math.max(0, ficaWages - ADDL_MEDICARE_WITHHOLD_START);
    var state = o.stateRate / 100 * fedWages;
    var post = o.postPer * o.periods;
    var net = gross - k401 - pretax - federal - ss - medicare - state - post;
    return {
      gross: gross, k401: k401, pretax: pretax, fedWages: fedWages, taxable: taxable,
      deduction: deduction, usedItemized: o.itemized > standard, credits: credits,
      federal: federal, marginal: bt.marginal, ss: ss, medicare: medicare, state: state,
      post: post, net: net, taxes: federal + ss + medicare + state
    };
  }

  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var o = {
      gross: num('tpSalary'), periods: parseInt(document.getElementById('tpFreq').value, 10),
      status: document.getElementById('tpStatus').value, k401Pct: num('tp401k'),
      pretaxPer: num('tpPretax'), kids: Math.round(num('tpKids')), otherDeps: Math.round(num('tpOtherDeps')),
      stateRate: num('tpState'), postPer: num('tpPosttax'), otherIncome: num('tpOtherIncome'),
      itemized: num('tpItemized'), you65: document.getElementById('tpYou65').checked,
      spouse65: document.getElementById('tpSpouse65').checked
    };
    if (!BRACKETS[o.status]) o.status = 'single';
    if (!(o.periods > 0)) o.periods = 26;
    var error = document.getElementById('tpError');
    var nums = [o.gross, o.k401Pct, o.pretaxPer, o.kids, o.otherDeps, o.stateRate, o.postPer, o.otherIncome, o.itemized];
    var bad = nums.some(function (v) { return !isFinite(v) || v < 0; }) ||
              o.gross > 1e9 || o.k401Pct > 100 || o.stateRate > 20 || o.kids > 20 || o.otherDeps > 20;
    var msg = 'Enter a salary, non-negative amounts, a 401(k) rate from 0 to 100% and a state rate from 0 to 20%.';
    if (!bad && o.gross * o.k401Pct / 100 + o.pretaxPer * o.periods + o.postPer * o.periods > o.gross) {
      bad = true;
      msg = 'Your deductions add up to more than your gross pay. Lower the 401(k) rate or the per-paycheck deductions.';
    }
    error.hidden = !bad;
    if (bad) { error.textContent = msg; return; }

    var r = compute(o), p = o.periods;
    setText('tpNet', money.format(r.net / p));
    setText('tpNetAnnual', money.format(r.net));
    setText('tpTaxPer', money.format(r.taxes / p));
    setText('tpEffective', r.gross > 0 ? pct.format(r.taxes / r.gross) : '0%');
    setText('tpMarginal', pct.format(r.marginal));
    setText('tpTaxable', money.format(r.taxable));

    var rows = [
      ['Gross pay', r.gross],
      ['401(k) / 403(b) contribution', -r.k401],
      ['Other pre-tax deductions', -r.pretax],
      ['Federal income tax', -r.federal],
      ['Social Security (6.2%)', -r.ss],
      ['Medicare', -r.medicare],
      ['State and local income tax', -r.state],
      ['After-tax deductions', -r.post],
      ['Take-home pay', r.net]
    ];
    document.getElementById('tpBreakdown').innerHTML = rows.map(function (row, i) {
      var cell = function (v) { if (Math.abs(v) < 0.005) return money.format(0); return v < 0 ? '−' + money.format(-v) : money.format(v); };
      var open = i === rows.length - 1 ? '<tr><th scope="row"><strong>' : '<tr><th scope="row">';
      var close = i === rows.length - 1 ? '</strong></th>' : '</th>';
      return open + row[0] + close + '<td>' + cell(row[1] / p) + '</td><td>' + cell(row[1]) + '</td></tr>';
    }).join('');

    var notes = [];
    if (r.gross * o.k401Pct / 100 > ELECTIVE_DEFERRAL_LIMIT) {
      notes.push('Your 401(k) amount is above the ' + TAX_YEAR + ' employee limit of ' + whole.format(ELECTIVE_DEFERRAL_LIMIT) +
                 ' (higher if you are 50 or older and make catch-up contributions).');
    }
    if (r.usedItemized) notes.push('Your itemized deductions are larger than the standard deduction, so they are used instead.');
    if (o.spouse65 && o.status !== 'mfj') notes.push('The spouse 65+ option only applies when filing jointly.');
    if (o.kids + o.otherDeps > 0 && r.federal === 0) notes.push('Your credits exceed your federal income tax, so federal tax is shown as zero. Part of the child tax credit may still be refundable when you file.');
    var noteEl = document.getElementById('tpNote');
    noteEl.hidden = notes.length === 0;
    noteEl.textContent = notes.join(' ');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('tpForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
